import backtrader as bt


class ROCBasedTechnicalStrategy(bt.Strategy):
    params = (
        ('fast_period', 20),
        ('slow_period', 50),
    )

    def __init__(self):
        self.fast_sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.fast_period
        )
        self.slow_sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.slow_period
        )
        self.crossover = bt.indicators.CrossOver(self.fast_sma, self.slow_sma)
        self.order = None

        self.true_positives = 0
        self.false_positives = 0
        self.true_negatives = 0
        self.false_negatives = 0
        self.true_positive_rate = 0.0
        self.false_positive_rate = 0.0
        self.confusion_matrix = [[0, 0], [0, 0]]

    def _update_roc_metrics(self):
        self.confusion_matrix = [
            [self.true_negatives, self.false_positives],
            [self.false_negatives, self.true_positives],
        ]
        positive_total = self.true_positives + self.false_negatives
        negative_total = self.false_positives + self.true_negatives
        self.true_positive_rate = (
            self.true_positives / positive_total if positive_total else 0.0
        )
        self.false_positive_rate = (
            self.false_positives / negative_total if negative_total else 0.0
        )

    def next(self):
        buy_signal = self.crossover[0] > 0
        positive_day = self.data.close[0] > self.data.open[0]
        negative_day = self.data.close[0] < self.data.open[0]

        if positive_day:
            if buy_signal:
                self.true_positives += 1
            else:
                self.false_negatives += 1
        elif negative_day:
            if buy_signal:
                self.false_positives += 1
            else:
                self.true_negatives += 1

        self._update_roc_metrics()

        if buy_signal and not self.position and self.order is None:
            self.order = self.buy(size=1)

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status == order.Completed and order.isbuy():
            self.order = self.close()
            return

        if order.status in [
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ]:
            self.order = None
